//! Actual container/decoder contract checks for the isolated patched cohort.
//! Synthetic PCM/encodes are generated by the Python runner; no checked-in media.
use std::{fs, io::Cursor};

use symphonia::core::{
    audio::GenericAudioBufferRef,
    codecs::audio::{AudioDecoder, AudioDecoderOptions},
    formats::{FormatReader, SeekMode, SeekTo, TrackType, probe::Hint},
    io::MediaSourceStream,
    packet::Packet,
    units::Timestamp,
};

fn fixture() -> Vec<u8> {
    fs::read(std::env::var_os("W09_M4A_FIXTURE").expect("generated M4A fixture")).unwrap()
}

fn reader(data: &[u8]) -> Box<dyn FormatReader + '_> {
    symphonia::default::get_probe()
        .probe(
            &Hint::new(),
            MediaSourceStream::new(Box::new(Cursor::new(data)), Default::default()),
            Default::default(),
            Default::default(),
        )
        .unwrap()
}

fn decoder(format: &dyn FormatReader, gapless: bool) -> Box<dyn AudioDecoder> {
    let params = format
        .default_track(TrackType::Audio)
        .unwrap()
        .codec_params
        .as_ref()
        .unwrap()
        .audio()
        .unwrap();
    symphonia::default::get_codecs()
        .make_audio_decoder(params, &AudioDecoderOptions::default().gapless(gapless))
        .unwrap()
}

fn append(block: GenericAudioBufferRef<'_>, output: &mut Vec<f32>, skip_frames: usize) {
    let channels = block.spec().channels().count();
    let mut scratch = vec![0.0; block.samples_interleaved()];
    block.copy_to_slice_interleaved(&mut scratch);
    output.extend_from_slice(&scratch[(skip_frames * channels).min(scratch.len())..]);
}

fn packets(data: &[u8]) -> (Box<dyn AudioDecoder>, Vec<Packet>) {
    let mut format = reader(data);
    let decoder = decoder(&*format, true);
    let mut packets = Vec::new();
    while let Some(packet) = format.next_packet().unwrap() {
        packets.push(packet);
    }
    (decoder, packets)
}

#[test]
fn actual_packets_and_decoder_agree_on_trim_units_and_total_frames() {
    let data = fixture();
    let mut format = reader(&data);
    let track = format.default_track(TrackType::Audio).unwrap();
    let expected = track.num_frames.unwrap();
    let params = track.codec_params.as_ref().unwrap().audio().unwrap();
    let rate = params.sample_rate.unwrap();
    let time_base = track.time_base.unwrap();
    assert_eq!(
        time_base
            .calc_time(Timestamp::new(i64::from(rate)))
            .unwrap(),
        symphonia::core::units::Time::from_ss(1, 0).unwrap()
    );
    let block_frames = params.max_frames_per_packet.unwrap();
    let mut decoder = decoder(&*format, true);
    let mut total = 0;
    let mut saw_start = false;
    let mut saw_end = false;
    while let Some(packet) = format.next_packet().unwrap() {
        assert_eq!(packet.block_dur().get(), block_frames);
        saw_start |= packet.trim_start.get() != 0;
        saw_end |= packet.trim_end.get() != 0;
        let block = decoder.decode_ref(&packet.as_packet_ref()).unwrap();
        assert_eq!(block.frames() as u64, packet.dur.get());
        total += packet.dur.get();
    }
    assert_eq!(total, expected);
    assert!(saw_start && saw_end);
}

#[test]
fn decoder_option_controls_trimming_and_borrowed_packets_preserve_pcm() {
    let data = fixture();
    let format = reader(&data);
    let mut trimmed = decoder(&*format, true);
    let mut untrimmed = decoder(&*format, false);
    let mut borrowed = decoder(&*format, true);
    let (_, packets) = packets(&data);
    for packet in &packets {
        let full = untrimmed.decode(packet).unwrap();
        let mut raw = Vec::new();
        append(full, &mut raw, 0);
        let mut actual = Vec::new();
        append(trimmed.decode(packet).unwrap(), &mut actual, 0);
        let mut ref_actual = Vec::new();
        append(
            borrowed.decode_ref(&packet.as_packet_ref()).unwrap(),
            &mut ref_actual,
            0,
        );
        assert_eq!(actual, ref_actual);
        let channels = trimmed.codec_params().channels.as_ref().unwrap().count();
        let start = packet.trim_start.get() as usize * channels;
        let end = raw.len() - packet.trim_end.get() as usize * channels;
        assert_eq!(&raw[start..end], actual);
    }
}

#[test]
fn invalid_trim_is_an_error_and_clears_last_decoded_output() {
    let data = fixture();
    let (mut decoder, packets) = packets(&data);
    let mut packet = packets[1].clone();
    decoder.decode(&packet).unwrap();
    assert!(decoder.last_decoded().frames() != 0);
    packet.trim_start = symphonia::core::units::Duration::MAX;
    assert!(decoder.decode_ref(&packet.as_packet_ref()).is_err());
    assert_eq!(decoder.last_decoded().frames(), 0);
    decoder.reset();
    packet.trim_start = symphonia::core::units::Duration::ZERO;
    assert!(decoder.decode_ref(&packet.as_packet_ref()).is_ok());
}

#[test]
fn seek_with_preroll_matches_the_corresponding_full_decode() {
    // This fixture disables perceptual noise substitution. PNS deliberately
    // synthesizes noise from a stateful RNG; an arbitrary random-access decode
    // is not required to reproduce the full stream's exact noise realization.
    let data = fixture();
    let full = crate::candidate::decode(&data, 16_777_216).unwrap();
    let frames = full.frame_count() as usize;
    let channels = full.channels as usize;
    let mut format = reader(&data);
    let id = format.default_track(TrackType::Audio).unwrap().id;
    let mut decoder = decoder(&*format, true);
    // Reuse the reader/decoder to cover backward seeks and reset of AAC state.
    for target in [frames - 1, 0, 1, 211, 1023, 1024, frames / 2, 2100] {
        let requested = Timestamp::new(target as i64);
        let actual = format
            .seek(
                SeekMode::Accurate,
                SeekTo::Timestamp {
                    ts: requested,
                    track_id: id,
                },
            )
            .unwrap();
        assert_eq!(actual.required_ts, requested);
        assert!(actual.actual_ts <= requested);
        decoder.reset();
        let mut tail = Vec::new();
        while let Some(packet) = format.next_packet().unwrap() {
            let start = packet.pts.get() + packet.trim_start.get() as i64;
            let skip = (target as i64 - start).max(0) as usize;
            append(decoder.decode(&packet).unwrap(), &mut tail, skip);
        }
        let expected = &full.samples[target * channels..];
        assert_eq!(tail.len(), expected.len(), "seek frame count at {target}");
        let max_error = tail
            .iter()
            .zip(expected)
            .map(|(a, b)| (a - b).abs())
            .fold(0.0f32, f32::max);
        assert!(
            max_error < 0.000_01,
            "AAC seek differs at {target}: max PCM error {max_error}"
        );
    }
    assert!(
        format
            .seek(
                SeekMode::Accurate,
                SeekTo::Timestamp {
                    ts: Timestamp::new(frames as i64),
                    track_id: id,
                }
            )
            .is_err()
    );
}

#[test]
fn restarting_a_pns_stream_is_deterministic_and_clears_output() {
    let data = fs::read(std::env::var_os("W09_M4A_PNS_FIXTURE").expect("PNS fixture")).unwrap();
    let expected = crate::candidate::decode(&data, 16_777_216).unwrap();
    let mut format = reader(&data);
    let id = format.default_track(TrackType::Audio).unwrap().id;
    let mut decoder = decoder(&*format, true);
    for _ in 0..3 {
        format
            .seek(
                SeekMode::Accurate,
                SeekTo::Timestamp {
                    ts: Timestamp::ZERO,
                    track_id: id,
                },
            )
            .unwrap();
        decoder.reset();
        assert_eq!(decoder.last_decoded().frames(), 0);
        let mut actual = Vec::new();
        while let Some(packet) = format.next_packet().unwrap() {
            append(decoder.decode(&packet).unwrap(), &mut actual, 0);
        }
        assert_eq!(actual, expected.samples, "restart inherited PNS state");
    }
}

#[test]
fn mp3_packet_valid_duration_matches_gapless_decoder_output() {
    let data = fs::read(std::env::var_os("W09_MP3_FIXTURE").expect("MP3 fixture")).unwrap();
    let mut format = reader(&data);
    let track = format.default_track(TrackType::Audio).unwrap();
    let expected = track.num_frames.unwrap();
    assert!(
        track.time_base.is_some(),
        "MPEG timestamps need a sample timebase"
    );
    let mut decoder = decoder(&*format, true);
    let mut total = 0;
    let mut trimmed = 0;
    while let Some(packet) = format.next_packet().unwrap() {
        let block = decoder.decode_ref(&packet.as_packet_ref()).unwrap();
        assert_eq!(
            block.frames() as u64,
            packet.dur.get(),
            "packet duration includes discarded frames"
        );
        assert_eq!(packet.block_dur().get(), 1152);
        trimmed += packet.trim_start.get() + packet.trim_end.get();
        total += packet.dur.get();
    }
    assert!(trimmed != 0);
    assert_eq!(total, expected);
}
